+	err := evolution.CheckFrozenGuard(target)
+	if err == nil {
+		t.Fatalf("expected ErrFrozenPath for %q, got nil", target)
+	}
+	if err != evolution.ErrFrozenPath {
+		t.Fatalf("expected ErrFrozenPath, got %v", err)
