+	t.Parallel()
+
+	got := DetermineOutcome(nil)
+	if got != OutcomeUnknown {
+		t.Errorf("DetermineOutcome(nil) = %q, want %q", got, OutcomeUnknown)
+	}
+
+	got = DetermineOutcome([]Event{})
+	if got != OutcomeUnknown {
+		t.Errorf("DetermineOutcome([]) = %q, want %q", got, OutcomeUnknown)
+	}
