+func splitYAMLDocs(data []byte) [][]byte {
+	var docs [][]byte
+	// \n--- 또는 파일 시작 --- 로 분리
+	// bytes.Split은 정확히 "---"만 있는 행을 기준으로 분리
+	lines := bytes.Split(data, []byte("\n"))
