+}
+
+// TestClient_Shutdown_IdempotentOnUnstarted verifies that Shutdown on an unstarted
+// (spawning state) client transitions to shutdown without error.
+func TestClient_Shutdown_IdempotentOnUnstarted(t *testing.T) {
