+	// 과거 시간으로 강제 설정
+	cache.mu.Lock()
+	entry := cache.entries["file:///touch.go"]
+	old := time.Now().Add(-1 * time.Minute)
+	entry.lastActivity = old
+	cache.entries["file:///touch.go"] = entry
+	cache.mu.Unlock()
+
+	cache.touch("file:///touch.go")
+
+	snap := cache.snapshot()
+	updated := snap["file:///touch.go"].lastActivity
