+	// 표준 입력을 읽고 아무것도 출력하지 않는 최소 스텁
+	if err := os.WriteFile(path, []byte("#!/bin/sh\ncat\n"), 0o755); err != nil {
+		t.Fatalf("writeFakeBinary: %v", err)
