+// pipeStream wraps two io.PipeReader+io.PipeWriter as a single io.ReadWriteCloser.
+type pipeStream struct {
+	r *io.PipeReader
+	w *io.PipeWriter
+}
+
+func newPipeStream() (*pipeStream, *io.PipeWriter) {
+	r, w := io.Pipe()
+	return &pipeStream{r: r, w: w}, w
